package xyz.jovanstoiljkovic.isa.repositories;import org.springframework.data.jpa.repository.Query;import org.springframework.stereotype.Repository;import xyz.jovanstoiljkovic.isa.models.Like;import java.util.List;@Repositorypublic interface LikeRepository extends BaseRepository<Like, Long>{    @Query("select l from like_entity l where l.user.id = ?1")    List<Like> findUserLikes(Long userId);}